const dataStr = $json.query;  

if (!dataStr) {
  return { isFeriadoOuFimSemana: false, error: 'query não informada' };
}

// Padroniza data
let data = new Date(dataStr);
if (isNaN(data.getTime())) {
  return { isFeriadoOuFimSemana: false, error: 'Data inválida em query' };
}

const ano = data.getFullYear();
const mes = String(data.getMonth() + 1).padStart(2, '0');
const dia = String(data.getDate()).padStart(2, '0');
const dataDM = `${dia}-${mes}`;
const ehFimSemana = data.getDay() === 0 || data.getDay() === 6;

try {
  // API feriados nacionais gratuitos
  const response = await fetch('https://rodriguesfas.github.io/holidays/national.json');
  const feriados = await response.json();

  const ehFeriado = feriados.some(f => f.date === dataDM);

  return {
    dataOriginal: dataStr,
    dataPadrao: `${ano}-${mes}-${dia}`,
    ehFeriadoNacional: ehFeriado,
    ehFimSemana,
    isFeriadoOuFimSemana: ehFeriado || ehFimSemana
  };
} catch (error) {
  return {
    isFeriadoOuFimSemana: ehFimSemana,
    error: 'Erro API: ' + error.message
  };
}
